import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]

    # For each x and right endpoint r, keep the largest L among
    # restrictions with X=x and R<=r. Such a restriction is contained
    # in [l,r] exactly when this value is at least l.
    best_left = [[-1] * (n + 1) for _ in range(n + 1)]
    p = 2
    for _ in range(m):
        l, r, x = data[p], data[p + 1], data[p + 2]
        p += 3
        if l > best_left[x][r]:
            best_left[x][r] = l
    for x in range(1, n + 1):
        row = best_left[x]
        for r in range(1, n + 1):
            if row[r - 1] > row[r]:
                row[r] = row[r - 1]

    # Interleaving counts for the relative orders in the two subtrees.
    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    # dp[l][r]: valid permutations on the interval [l,r], using its
    # values in relative order. Empty intervals have one arrangement.
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                if best_left[k][r] >= l:
                    continue  # A condition forbids k being the interval maximum.
                left_size = k - l
                total += (comb[length - 1][left_size]
                          * dp[l][k - 1] * dp[k + 1][r])
            dp[l][r] = total % MOD

    print(dp[1][n])

if __name__ == '__main__':
    main()

