import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]

    factors = []
    primes = set()
    for x in a:
        fs = {}
        z = x
        p = 2
        while p * p <= z:
            while z % p == 0:
                fs[p] = fs.get(p, 0) + 1
                z //= p
            p += 1
        if z > 1:
            fs[z] = fs.get(z, 0) + 1
        factors.append(fs)
        primes.update(fs)

    ans = 1
    for p in primes:
        exponents = [fs.get(p, 0) for fs in factors]
        total = sum(exponents)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * p % MOD

        # dp0[h]: walks at height h which have not visited zero;
        # dp1[h]: walks at height h which have visited zero.
        dp0 = [0] * (total + 1)
        dp1 = [0] * (total + 1)
        for h in range(total + 1):
            if h == 0:
                dp1[h] = 1
            else:
                dp0[h] = powers[h]

        for e in exponents:
            ndp0 = [0] * (total + 1)
            ndp1 = [0] * (total + 1)
            if e == 0:
                for h in range(total + 1):
                    weight = powers[h]
                    ndp0[h] = dp0[h] * weight % MOD
                    ndp1[h] = dp1[h] * weight % MOD
            else:
                for h in range(total + 1):
                    v0, v1 = dp0[h], dp1[h]
                    if not (v0 or v1):
                        continue
                    for nh in (h - e, h + e):
                        if nh < 0 or nh > total:
                            continue
                        weight = powers[nh]
                        if nh == 0:
                            ndp1[0] = (ndp1[0] + (v0 + v1) * weight) % MOD
                        else:
                            ndp0[nh] = (ndp0[nh] + v0 * weight) % MOD
                            ndp1[nh] = (ndp1[nh] + v1 * weight) % MOD
            dp0, dp1 = ndp0, ndp1

        ans = ans * (sum(dp1) % MOD) % MOD

    print(ans)

solve()

