import sys
from array import array

def main():
    input = sys.stdin.buffer.readline
    N, Q = map(int, input().split())
    parent = array('i', range(N))
    left = array('i', range(N))
    right = array('i', range(N))
    color = array('i', range(1, N + 1))
    cnt = array('i', [1]) * (N + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def merge(a, b):
        a = find(a)
        b = find(b)
        if a == b:
            return a
        parent[b] = a
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    out = []
    for _ in range(Q):
        query = list(map(int, input().split()))
        if query[0] == 1:
            _, x, c = query
            r = find(x - 1)
            old = color[r]
            if old != c:
                length = right[r] - left[r] + 1
                cnt[old] -= length
                cnt[c] += length
                color[r] = c
            while left[r] > 0:
                lroot = find(left[r] - 1)
                if color[lroot] != c:
                    break
                r = merge(r, lroot)
            while right[r] + 1 < N:
                rr = find(right[r] + 1)
                if color[rr] != c:
                    break
                r = merge(r, rr)
        else:
            out.append(str(cnt[query[1]]))
    print('\n'.join(out))

if __name__ == '__main__':
    main()

