def main():
    input=sys.stdin.buffer.readline
    N,M,Q=map(int,input().split())
    edges=[]
    for _ in range(M):
        a,b,c=map(int,input().split()); edges.append((a-1,b-1,c))
    queries=[]
    for _ in range(Q): queries.append(tuple(map(int,input().split())))
    closed=[False]*M
    ans=[]; p=0; B=30; INF=10**30
    while p<Q:
        end=p; cnt=0
        while end<Q:
            if queries[end][0]==1:
                if cnt==B: break
                cnt+=1
            end+=1
        cand=[queries[t][1]-1 for t in range(p,end) if queries[t][0]==1]
        d=[[INF]*N for _ in range(N)]
        for i in range(N): d[i][i]=0
        cset=set(cand)
        for eid,(a,b,w) in enumerate(edges):
            if not closed[eid] and eid not in cset:
                if w<d[a][b]: d[a][b]=d[b][a]=w
        floyd(d)
        verts=sorted({x for eid in cand for x in edges[eid][:2]})
        pos={v:i for i,v in enumerate(verts)}
        def make_aux():
            z=[[d[a][b] for b in verts] for a in verts]
            for eid in cand:
                if not closed[eid]:
                    a,b,w=edges[eid]; x=pos[a]; y=pos[b]
                    if w<z[x][y]: z[x][y]=z[y][x]=w
            floyd(z)
            return z
        aux=make_aux() if verts else []
        for t in range(p,end):
            q=queries[t]
            if q[0]==1:
                eid=q[1]-1; closed[eid]=True
                aux=make_aux()
            else:
                x,y=q[1]-1,q[2]-1
                best=d[x][y]
                for i,a in enumerate(verts):
                    u=d[x][a]
                    if u>=best: continue
                    row=aux[i]
                    for j,b in enumerate(verts):
                        v=d[b][y]
                        if u+row[j]+v<best: best=u+row[j]+v
                ans.append(str(best if best<INF else -1))
        p=end
    sys.stdout.write('\n'.join(ans))
if __name__=='__main__': main()

