import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    machines = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        machines.append((a, p, b, q))

    def minimum_cost(k, a, p, b, q):
        period = b // gcd(a, b)
        xmax = (k + a - 1) // a
        best = 10**30
        for r in range(min(period, xmax + 1)):
            tmax = (xmax - r) // period
            for t in (0, tmax):
                x_count = r + t * period
                y_count = max(0, (k - a * x_count + b - 1) // b)
                best = min(best, x_count * p + y_count * q)
        return best

    def feasible(k):
        total = 0
        for a, p, b, q in machines:
            total += minimum_cost(k, a, p, b, q)
            if total > budget:
                return False
        return True

    low, high = 0, 100 * budget + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

