class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        # Stirling numbers of the second kind, one row at a time.
        s = [0] * (min(n, x) + 1)
        s[0] = 1
        for i in range(1, n + 1):
            upto = min(i, x)
            for k in range(upto, 0, -1):
                s[k] = (s[k - 1] + k * s[k]) % MOD
            s[0] = 0
        ans = 0
        falling = 1
        yp = 1
        for k in range(1, min(n, x) + 1):
            falling = falling * (x - k + 1) % MOD
            yp = yp * y % MOD
            ans = (ans + s[k] * falling % MOD * yp) % MOD
        return ans

if __name__ == '__main__':
    for args in [(1,2,3),(5,2,1),(3,3,4)]:
        print(Solution().numberOfWays(*args))

