class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # steps[x] is the number of popcount operations needed to reach 1.
        steps = [0] * (length + 1)
        for x in range(2, length + 1):
            steps[x] = 1 + steps[x.bit_count()]

        # Any x with popcount m takes one operation to reach m, then steps[m].
        allowed = [steps[m] <= k - 1 for m in range(length + 1)]

        # Binomial coefficients modulo MOD.
        choose = [[0] * (length + 1) for _ in range(length + 1)]
        choose[0][0] = 1
        for i in range(1, length + 1):
            choose[i][0] = choose[i][i] = 1
            for j in range(1, i):
                choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

        answer = 0
        ones_so_far = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                # Set this bit to 0, then choose the remaining required ones.
                for m in range(1, length + 1):
                    if allowed[m]:
                        need = m - ones_so_far
                        if 0 <= need <= remaining:
                            answer = (answer + choose[remaining][need]) % MOD
                ones_so_far += 1

        return answer

