class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        steps = [0] * (L + 1)
        for x in range(2, L + 1):
            steps[x] = 1 + steps[x.bit_count()]

        good = [steps[m] <= k - 1 for m in range(L + 1)]
        C = [[0] * (L + 1) for _ in range(L + 1)]
        C[0][0] = 1
        for i in range(1, L + 1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        ans = 0
        used = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = L - i - 1
                for m in range(1, L + 1):
                    if good[m]:
                        need = m - used
                        if 0 <= need <= rem:
                            ans = (ans + C[rem][need]) % MOD
                used += 1
        return ans

