import sys
import heapq

def solve():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    graph = [row.decode() for row in data[1:]]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for a in range(n):
        for b, ch in enumerate(graph[a]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[a][c].append(b)
                incoming[b][c].append(a)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-' and dist[i][j] > 1:
                dist[i][j] = 1
                heapq.heappush(heap, (1, i, j))

    while heap:
        length, u, v = heapq.heappop(heap)
        if dist[u][v] != length:
            continue
        candidate = length + 2
        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
            for a in left:
                row = dist[a]
                for b in right:
                    if candidate < row[b]:
                        row[b] = candidate
                        heapq.heappush(heap, (candidate, a, b))

    sys.stdout.write('\n'.join(' '.join(str(-1 if x == inf else x) for x in row) for row in dist))

if __name__ == '__main__':
    solve()

