import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n

    for z in range(m):
        u = data[2 + 2 * z] - 1
        v = data[3 + 2 * z] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Row-reduce the adjacency matrix over GF(2).
    mat = rows[:]
    pivots = []
    rank = 0
    for col in range(n):
        pivot_row = next((i for i in range(rank, n) if (mat[i] >> col) & 1), None)
        if pivot_row is None:
            continue
        mat[rank], mat[pivot_row] = mat[pivot_row], mat[rank]
        for i in range(n):
            if i != rank and ((mat[i] >> col) & 1):
                mat[i] ^= mat[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free_cols = [c for c in range(n) if c not in pivot_set]
    basis = []
    for col in free_cols:
        vec = 1 << col
        for row, pivot_col in enumerate(pivots):
            if (mat[row] >> col) & 1:
                vec |= 1 << pivot_col
        basis.append(vec)

    # Use one independent bit per nullspace basis vector. The offset is
    # purely cosmetic; keep all used positions within the allowed 60 bits.
    offset = 2 if n > 1 and len(basis) <= 58 else 0
    values = [0] * n
    for j, vec in enumerate(basis):
        for v in range(n):
            if (vec >> v) & 1:
                values[v] |= 1 << (j + offset)

    if any(x == 0 for x in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == "__main__":
    main()

