from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        unused = set(range(1, n + 1))
        result = []
        prev_parity = None  # 1 for odd, 0 for even

        for pos in range(n):
            chosen = None
            for x in sorted(unused):
                parity = x & 1
                if prev_parity is not None and parity == prev_parity:
                    continue

                remaining = unused - {x}
                odd = sum(y & 1 for y in remaining)
                even = len(remaining) - odd
                slots = n - pos - 1

                if slots:
                    next_parity = 1 - parity
                    odd_slots = (slots + 1) // 2 if next_parity == 1 else slots // 2
                    even_slots = slots - odd_slots
                    if odd != odd_slots or even != even_slots:
                        continue
                elif odd or even:
                    continue

                block = math.factorial(odd) * math.factorial(even)
                if k > block:
                    k -= block
                else:
                    chosen = x
                    break

            if chosen is None:
                return []
            result.append(chosen)
            unused.remove(chosen)
            prev_parity = chosen & 1

        return result

