class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # Powers of ten modulo k, used to compute each mirrored digit's
        # contribution to the complete number.
        p10 = [1] * n
        for i in range(1, n):
            p10[i] = (p10[i - 1] * 10) % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = p10[i]
            if j != i:
                c += p10[j]
            coeff.append(c % k)

        # suffix[i] has bit r set iff positions i onward can contribute
        # residue r modulo k.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # Empty suffix contributes zero.
        for i in range(m - 1, -1, -1):
            values = {(d * coeff[i]) % k for d in range(10)}
            next_mask = suffix[i + 1]
            mask = 0
            for r in range(k):
                if (next_mask >> r) & 1:
                    for v in values:
                        mask |= 1 << ((r + v) % k)
            suffix[i] = mask

        # Greedily choose each digit, retaining only choices completable
        # by a suffix whose contribution makes the total divisible by k.
        digits = [0] * m
        remainder = 0
        for i in range(m):
            minimum = 1 if i == 0 else 0
            for d in range(9, minimum - 1, -1):
                new_remainder = (remainder + d * coeff[i]) % k
                needed = (-new_remainder) % k
                if (suffix[i + 1] >> needed) & 1:
                    digits[i] = d
                    remainder = new_remainder
                    break

        left = ''.join(map(str, digits))
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

