from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [tuple(data[i:i + 2]) for i in range(2, len(data), 2)]

    # Inner-to-outer order: descending B / (A - 1).
    # A == 1 is treated as an infinite ratio.
    def compare(x, y):
        a, b = x
        c, d = y
        if a == 1 or c == 1:
            if a == c:
                return 0
            return -1 if a == 1 else 1
        left = b * (c - 1)
        right = d * (a - 1)
        if left > right:
            return -1
        if left < right:
            return 1
        return 0

    funcs.sort(key=cmp_to_key(compare))
    dp = [None] * (k + 1)
    dp[0] = 1
    processed = 0
    for a, b in funcs:
        processed = min(k, processed + 1)
        for count in range(processed, 0, -1):
            if dp[count - 1] is not None:
                value = a * dp[count - 1] + b
                if dp[count] is None or value > dp[count]:
                    dp[count] = value
    print(dp[k])

