class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        f = [0] * 26
        for ch in s:
            f[ord(ch) - 97] += 1
        n = len(s)
        # For a fixed common frequency, process the alphabet from left to right.
        # The state is the number of characters carried to the next letter.
        ans = n
        for k in range(1, max(f) + 2):
            dp = {0: 0}
            for i in range(26):
                ndp = {}
                for carry, cost in dp.items():
                    available = carry + f[i]
                    for want in (0, k):
                        # Choose how many excess characters to pass forward.
                        # For each outgoing amount, the remainder is deleted or inserted.
                        for out in range(available + 1):
                            val = cost + out + abs(available - want - out)
                            if val < ndp.get(out, n + 1):
                                ndp[out] = val
                dp = ndp
            ans = min(ans, dp.get(0, n + 1))
        return ans

