import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    pos = 3
    values = data[pos:pos+n] + data[pos+n:pos+n+m] + data[pos+n+m:pos+n+m+l]

    initial_t = (1 << n) - 1
    initial_a = ((1 << m) - 1) << n
    all_cards = (1 << len(values)) - 1

    @lru_cache(None)
    def can_win(takahashi, aoki, turn):
        hand = takahashi if turn == 0 else aoki
        if hand == 0:
            return False

        table = all_cards ^ (takahashi | aoki)
        remaining = hand
        while remaining:
            played = remaining & -remaining
            remaining -= played
            played_value = values[played.bit_length() - 1]

            next_t = takahashi ^ played if turn == 0 else takahashi
            next_a = aoki ^ played if turn == 1 else aoki

            # Put the played card on the table without taking another card.
            if not can_win(next_t, next_a, 1 - turn):
                return True

            # Or take any card that was already on the table and is smaller.
            candidates = table
            while candidates:
                taken = candidates & -candidates
                candidates -= taken
                if values[taken.bit_length() - 1] < played_value:
                    if turn == 0:
                        if not can_win(next_t | taken, next_a, 1):
                            return True
                    else:
                        if not can_win(next_t, next_a | taken, 0):
                            return True

        return False

    print("Takahashi" if can_win(initial_t, initial_a, 0) else "Aoki")

