from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first = p.index('*')
        second = p.index('*', first + 1)
        parts = (p[:first], p[first + 1:second], p[second + 1:])
        n = len(s)

        def occurrences(word):
            m = len(word)
            if m == 0:
                return list(range(n + 1))

            # KMP prefix table
            prefix = [0] * m
            matched = 0
            for i in range(1, m):
                while matched and word[i] != word[matched]:
                    matched = prefix[matched - 1]
                if word[i] == word[matched]:
                    matched += 1
                prefix[i] = matched

            result = []
            matched = 0
            for i, ch in enumerate(s):
                while matched and ch != word[matched]:
                    matched = prefix[matched - 1]
                if ch == word[matched]:
                    matched += 1
                if matched == m:
                    result.append(i - m + 1)
                    matched = prefix[matched - 1]
            return result

        starts, middles, ends = (occurrences(part) for part in parts)
        len_start, len_middle, len_end = map(len, parts)
        best = n + 1

        for start in starts:
            middle_index = bisect_left(middles, start + len_start)
            if middle_index == len(middles):
                continue
            middle = middles[middle_index]
            end_index = bisect_left(ends, middle + len_middle)
            if end_index < len(ends):
                best = min(best, ends[end_index] + len_end - start)

        return -1 if best == n + 1 else best

