import sys

def main():
    data = sys.stdin.buffer.read().split()
    K = int(data[0])
    a, b = data[1], data[2]
    n, m = len(a), len(b)

    if abs(n - m) > K:
        print("No")
        return

    # k = i - j; each wavefront stores the furthest i reachable
    # on diagonal k using at most the current number of edits.
    def extend(k, i):
        j = i - k
        while i < n and j < m and a[i] == b[j]:
            i += 1
            j += 1
        return i

    prev = {0: extend(0, 0)}
    if prev[0] == n and n == m:
        print("Yes")
        return

    for score in range(1, K + 1):
        cur = {}
        for k in range(-score, score + 1):
            best = -1
            # Replace a character: same diagonal.
            if k in prev:
                best = max(best, prev[k] + 1)
            # Delete from a: diagonal increases by one.
            if k - 1 in prev:
                best = max(best, prev[k - 1] + 1)
            # Insert into a: diagonal decreases by one.
            if k + 1 in prev:
                best = max(best, prev[k + 1])

            if best < 0:
                continue
            j = best - k
            if best > n or j < 0 or j > m:
                continue
            i = extend(k, best)
            cur[k] = i
            if i == n and i - k == m:
                print("Yes")
                return
        prev = cur

    print("No")

