from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Construct the exact recursive postorder without recursion-depth risk.
        order = []
        stack = [(0, False)]
        while stack:
            v, done = stack.pop()
            if done:
                order.append(v)
            else:
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))

        pos = [0] * n
        for i, v in enumerate(order):
            pos[v] = i

        # A subtree occupies one contiguous interval in postorder.
        sizes = [1] * n
        for v in order:
            if v != 0:
                sizes[parent[v]] += sizes[v]

        text = ''.join(s[v] for v in order)

        # Manacher radii permit exact O(1) palindrome tests for any interval.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = []
        for v in range(n):
            start = pos[v] - sizes[v] + 1
            end = pos[v] + 1
            length = end - start
            if length & 1:
                center = (start + end - 1) // 2
                answer.append(odd[center] >= length // 2 + 1)
            else:
                center = (start + end) // 2
                answer.append(even[center] >= length // 2)
        return answer

