from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix indices with equal residues modulo k differ by a multiple of k.
        # Keep the smallest earlier prefix sum for each residue.
        min_prefix = [None] * k
        min_prefix[0] = 0

        prefix = 0
        best = None
        for j, value in enumerate(nums, 1):
            prefix += value
            residue = j % k

            if min_prefix[residue] is not None:
                candidate = prefix - min_prefix[residue]
                if best is None or candidate > best:
                    best = candidate

            if min_prefix[residue] is None or prefix < min_prefix[residue]:
                min_prefix[residue] = prefix

        return best

