import sys
import math
import bisect

N = int(sys.stdin.buffer.readline())
root = math.isqrt(N)

# Generate all primes up to floor(sqrt(N)).
sieve = bytearray(b'\x01') * (root + 1)
if root >= 0:
    sieve[0] = 0
if root >= 1:
    sieve[1] = 0
for i in range(2, math.isqrt(root) + 1):
    if sieve[i]:
        start = i * i
        sieve[start:root + 1:i] = b'\x00' * (((root - start) // i) + 1)
primes = [i for i in range(2, root + 1) if sieve[i]]

# Forms p^8 and p^2 q^2 for distinct primes p < q.
answer = 0
for p in primes:
    if p ** 8 <= N:
        answer += 1
    else:
        break

for p in primes:
    if p * p >= root:
        break
    # q <= floor(sqrt(N)) // p, with q > p
    limit = root // p
    answer += bisect.bisect_right(primes, limit) - bisect.bisect_right(primes, p)

print(answer)

