class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def reachable_values(x: int) -> set[int]:
            digits = list(str(x))
            reachable = {x}  # The operation may be skipped.
            for i in range(len(digits)):
                for j in range(i + 1, len(digits)):
                    digits[i], digits[j] = digits[j], digits[i]
                    # int() correctly permits leading zeros after a swap.
                    reachable.add(int(''.join(digits)))
                    digits[i], digits[j] = digits[j], digits[i]
            return reachable

        reachable = [reachable_values(x) for x in nums]
        count = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[j] in reachable[i] or nums[i] in reachable[j]:
                    count += 1
        return count

