class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        count = {}
        for value in nums:
            count[value] = count.get(value, 0) + 1

        answer = None
        for special_sum in count:
            outlier = total - 2 * special_sum
            available = count.get(outlier, 0)
            if outlier == special_sum:
                available -= 1  # Reserve a distinct index for the sum element.
            if available > 0 and (answer is None or outlier > answer):
                answer = outlier
        return answer

