from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Bit s is set when sum s is achievable for this index.
        reachable = [1] * n
        limits = [(1 << (x + 1)) - 1 for x in nums]

        def all_zero_possible() -> bool:
            return all((reachable[i] >> nums[i]) & 1 for i in range(n))

        if all_zero_possible():
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                reachable[i] = (reachable[i] | (reachable[i] << value)) & limits[i]
            if all_zero_possible():
                return k

        return -1

