class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = 10000
        prime = [True] * limit
        prime[0] = prime[1] = False
        for p in range(2, 100):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        width = len(str(n))
        inf = 10**30
        dist = {n: n}
        pq = [(n, n)]

        while pq:
            cost, value = heapq.heappop(pq)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            digits = str(value).zfill(width)
            for i, char in enumerate(digits):
                digit = ord(char) - ord('0')
                for new_digit in (digit - 1, digit + 1):
                    if 0 <= new_digit <= 9 and not (i == 0 and new_digit == 0):
                        neighbor = int(digits[:i] + str(new_digit) + digits[i + 1:])
                        if not prime[neighbor]:
                            new_cost = cost + neighbor
                            if new_cost < dist.get(neighbor, inf):
                                dist[neighbor] = new_cost
                                heapq.heappush(pq, (new_cost, neighbor))

        return -1

