class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] = LCP(nums, nums[i:])
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # lcp[i][j] is the common-prefix length of nums[i:] and nums[j:].
        # Compact storage keeps the O(n^2) table within the memory limit.
        lcp = array('H', [0]) * (n * n)
        for i in range(n - 2, 0, -1):
            row = i * n
            next_row = (i + 1) * n
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]:
                    lcp[row + j] = 1 + (lcp[next_row + j + 1] if j + 1 < n else 0)

        answer = 0
        for i in range(1, n - 1):
            first_condition = z[i] >= i
            row = i * n
            for j in range(i + 1, n):
                if first_condition or lcp[row + j] >= j - i:
                    answer += 1
        return answer

