class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        # Z values: common prefix with nums[0:]
        z = [0] * n
        l = r = 0
        for i in range(1, n):
            if i <= r:
                z[i] = min(r - i + 1, z[i - l])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > r:
                l, r = i, i + z[i] - 1
        # LCP table in compact unsigned-short storage.
        from array import array
        dp = array('H', [0]) * (n * n)
        for i in range(n - 2, 0, -1):
            base = i * n
            nxt = base + n + 1
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]:
                    dp[base + j] = 1 + dp[nxt + j]
        ans = 0
        for i in range(1, n - 1):
            base = i * n
            first_ok = z[i] >= i
            for j in range(i + 1, n):
                if first_ok or dp[base + j] >= j - i:
                    ans += 1
        return ans

