        print('Yes' if mismatches <= 1 else 'No')
        return
    # Check if the shorter string is obtainable by deleting one character from the longer.
    if len(s) > len(t):
        longer, shorter = s, t
    else:
        longer, shorter = t, s
    i = j = 0
    skipped = False
    while i < len(longer) and j < len(shorter):
        if longer[i] == shorter[j]:
            i += 1
            j += 1
        elif skipped:
            print('No')
            return
        else:
            skipped = True
            i += 1
    print('Yes')

