class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        total = 0

        for left in range(len(word)):
            seen_vowels = set()
            consonants = 0

            for right in range(left, len(word)):
                char = word[right]
                if char in vowels:
                    seen_vowels.add(char)
                else:
                    consonants += 1
                    if consonants > k:
                        break

                if consonants == k and len(seen_vowels) == 5:
                    total += 1

        return total

