class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {tuple(p) for p in points}
        xs = sorted({x for x, _ in points})
        ys = sorted({y for _, y in points})
        best = -1

        for i in range(len(xs)):
            for j in range(i + 1, len(xs)):
                x1, x2 = xs[i], xs[j]
                for k in range(len(ys)):
                    for l in range(k + 1, len(ys)):
                        y1, y2 = ys[k], ys[l]
                        corners = ((x1, y1), (x1, y2), (x2, y1), (x2, y2))
                        if not all(corner in point_set for corner in corners):
                            continue

                        # A point other than the four corners on or inside the
                        # rectangle violates the constraint.
                        if any(x1 <= x <= x2 and y1 <= y <= y2 and
                               (x, y) not in corners for x, y in point_set):
                            continue

                        best = max(best, (x2 - x1) * (y2 - y1))

        return best

